// ============================================================
// 书旗 App 12.7.0.268 · 原生书源脚本库（v2 · 段评）
// 书旗算法：ALG-1 明文签名 / ALG-2 keystream / ALG-5 正文解码
// 段评数据：起点 m 站 chapterReview（游客态，_csrfToken 自造即可）
// ============================================================

// ---------- 常量 ----------
var SQ = {
  host: 'https://ocean.shuqireader.com',
  ua: 'okhttp/3.12.13',
  skey: '467694bd8912441cae8498b3c7e4282c',
  gatewayKey: 'sq_app_gateway',
  sqSv: '1.0',
  sv: '3.0',
  sgAppKey: '23011413',
  appUserId: '8158804976',
  ciUid: '8000000'
};

var QD = {
  host: 'https://m.qidian.com',
  ua: 'Mozilla/5.0 (Linux; U; Android 13; zh-cn; MI 11) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/120 Mobile Safari/537.36'
};

// 设备画像：服务端不严格校验，抄死一份真机常量
var SQ_PUB = {
  soft_id: '1', user_id: '8158804976', userId: '8158804976',
  ver: '261013', subVer: 'sqrelease', appVer: '12.7.0.268', theme: 'day',
  platform: 'an', placeid: '1069', sdk: '32', cpu: 'x86_64', pkg_cpu: 'arm64-v8a',
  wh: '900x1600', msv: '3', vc: '5d73', mod: 'BVL-AN16', manufacturer: 'HONOR',
  brand: 'HONOR', net_type: 'wifi', net_type_str: 'wifi', first_placeid: 'src1069',
  aak: 'a3a840', utype: 'pre_vip', net: '4', net_env: '4', permissionType: '0',
  personalized: '1', contentRecom: '1', scene_code: '', rom: '12',
  sqUniqDeviceId: '', utdid: '', sn: '', umidtoken: '', otdd: ''
};

var SQ_DEV_KEYS = ['sqUniqDeviceId', 'utdid', 'sn', 'umidtoken', 'otdd'];

var SQ_ORDER = ['soft_id','user_id','userId','ver','subVer','appVer','theme','platform','placeid',
  'sdk','cpu','pkg_cpu','wh','msv','enc','vc','mod','manufacturer','brand','net_type',
  'net_type_str','first_placeid','aak','utype','net','net_env','permissionType','personalized',
  'contentRecom','scene_code','rom','sqUniqDeviceId','utdid','sn','umidtoken','otdd'];

var SQ_NOSIGN = { sign:1, key:1, _public:1, _reqid:1, _beta:1, _:1, X:1,
  XNEBULAXMLHTTPREQUEST:1, callbackUrl:1 };

// ---------- ALG-2：keystream（base64 内嵌，2048 字节） ----------
var SQ_KS_B64 = '';
var SQ_KS = null;
// 必须用 base64Bytes 而不是 unbase64：keystream 不是合法 UTF-8，unbase64 会被替换成 U+FFFD
function sqKs() {
  if (SQ_KS) return SQ_KS;
  SQ_KS = native.base64Bytes(SQ_KS_B64);
  return SQ_KS;
}
function sqEnc(plain) {
  var ks = sqKs();
  var pb = native.bytes(plain);
  if (pb.length > ks.length) throw new Error('keystream too short');
  var out = [];
  for (var i = 0; i < pb.length; i++) out.push((pb[i] ^ ks[i]) & 255);
  return native.bytesBase64(out);
}
function sqDec(b64) {
  var ks = sqKs();
  var cb = native.base64Bytes(b64);
  var out = [];
  for (var i = 0; i < cb.length; i++) out.push((cb[i] ^ ks[i]) & 255);
  return native.fromBytes(out);
}

// ---------- ALG-1：明文签名 ----------
function sqSign(pairs, skey) {
  var keys = [];
  for (var k in pairs) {
    if (pairs.hasOwnProperty(k) && !SQ_NOSIGN[k]) keys.push(k);
  }
  var hasSqSv = false;
  for (var j = 0; j < keys.length; j++) if (keys[j] === 'sqSv') hasSqSv = true;
  if (!hasSqSv) keys.push('sqSv');
  keys.sort();
  var raw = '';
  for (var i = 0; i < keys.length; i++) {
    var kk = keys[i], vv = pairs[kk];
    raw += kk + '=' + (vv === undefined || vv === null || vv === '' ? '' : native.urlencode(String(vv))) + '&';
  }
  return native.md5(raw + 'skey=' + (skey || SQ.skey));
}

// ---------- enc 参数 ----------
function sqEnc18(uid, tsIn) {
  var ts = String(tsIn === undefined || tsIn === null ? Date.now() : tsIn);
  while (ts.length < 13) ts = '2' + ts;
  if (ts.length > 13) ts = ts.substring(0, 13);
  var u = Number(uid) || 0;
  if (u === 0) u = 24697;
  var key = Number((ts[1] + ts[3] + ts[5] + ts[8] + ts[6]) || '0') || 0;
  var j = key !== 0 ? key * u : 12347 * u;
  return String(j).slice(-5) + ts;
}

// ---------- 设备身份（每安装一份，存 vars 复用） ----------
function sqHex(nBytes) {
  var h = '';
  for (var i = 0; i < nBytes; i++) {
    var b = Math.floor(Math.random() * 256);
    h += (b < 16 ? '0' : '') + b.toString(16);
  }
  return h;
}
function sqB64Rand(nBytes) {
  var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  var out = '';
  for (var i = 0; i < nBytes; i++) {
    out += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return out;
}
function sqDevice() {
  var raw = '';
  try { raw = String(vars.get('sqDev') || ''); } catch (e0) { raw = ''; }
  if (raw) {
    try {
      var o = JSON.parse(raw);
      if (o && o.sqUniqDeviceId) return o;
    } catch (e1) {}
  }
  var dev = {
    sqUniqDeviceId: sqB64Rand(22),
    utdid: sqB64Rand(28),
    sn: sqHex(8),
    umidtoken: sqHex(20),
    otdd: sqB64Rand(22)
  };
  try { vars.set('sqDev', JSON.stringify(dev)); } catch (e2) {}
  return dev;
}

// ---------- x-sq-public 明文串 ----------
function sqPublicStr(uid, ts, enc, devIn) {
  var dev = devIn || sqDevice();
  var p = {};
  for (var k in SQ_PUB) if (SQ_PUB.hasOwnProperty(k)) p[k] = String(SQ_PUB[k]);
  for (var d = 0; d < SQ_DEV_KEYS.length; d++) p[SQ_DEV_KEYS[d]] = String(dev[SQ_DEV_KEYS[d]] || '');
  p.user_id = String(uid);
  p.userId = String(uid);
  p.platform = '2';
  p.enc = String(enc);
  p.timestamp = String(ts);
  var out = '';
  for (var i = 0; i < SQ_ORDER.length; i++) {
    var kk = SQ_ORDER[i];
    if (!(kk in p)) continue;
    out += kk + '=' + sqPubEnc(p[kk]) + '&';
  }
  return out;
}
function sqPubEnc(s) {
  return native.urlencode(String(s)).replace(/\+/g, '%20').replace(/\*/g, '%2A').replace(/%7E/g, '~');
}

// ---------- 加密口请求体 ----------
function sqAppBody(biz, uidIn, tsIn) {
  var uid = String(uidIn || SQ.appUserId);
  var ts = String(tsIn || Date.now());
  var enc = sqEnc18(uid, ts);
  var dev = sqDevice();
  var p = {};
  for (var k in SQ_PUB) if (SQ_PUB.hasOwnProperty(k)) p[k] = String(SQ_PUB[k]);
  for (var d = 0; d < SQ_DEV_KEYS.length; d++) p[SQ_DEV_KEYS[d]] = String(dev[SQ_DEV_KEYS[d]] || '');
  p.user_id = uid;
  p.userId = uid;
  p.platform = 'an';
  p.enc = enc;
  p.timestamp = ts;
  for (var b in (biz || {})) if (biz.hasOwnProperty(b)) p[b] = String(biz[b]);
  p.isTeenMode = '0';
  p.sqSv = SQ.sqSv;
  p.sign = sqSign(p, SQ.skey);
  p.key = SQ.gatewayKey;
  return {
    body: 'data=' + encodeURIComponent(sqEnc(JSON.stringify(p))),
    headers: {
      'content-type': 'application/x-www-form-urlencoded',
      'user-agent': SQ.ua,
      'x-sq-req-platform': 'an',
      'x-sq-s-key': SQ.sgAppKey,
      'x-sq-sv': SQ.sv,
      'x-sq-public': sqEnc(sqPublicStr(uid, ts, enc)),
      'x-sq-req-encrypt': 'sdk',
      'x-sq-req-encrypt-param': 'x-sq-public',
      'x-sq-api-encrypt': '1'
    }
  };
}

// ---------- ALG-5：正文解码 ----------
function sqRot(s) {
  return String(s || '').replace(/[A-Za-z]/g, function (ch) {
    var upper = ch === ch.toUpperCase();
    var k = (ch.toLowerCase().charCodeAt(0) - 83) % 26 || 26;
    var r = String.fromCharCode(k + 96);
    return upper ? r.toUpperCase() : r;
  });
}
function sqDecodeContent(s) {
  var t = String(s || '');
  if (!t) return '';
  var plain;
  try { plain = native.unbase64(sqRot(t)); }
  catch (e) { plain = sqRot(t); }
  return plain.replace(/<br\s*\/?>/gi, '\n');
}

// ---------- 归一化 ----------
function sqWan(n) {
  var v = Number(n) || 0;
  if (v >= 100000000) return Math.round(v / 1000000) / 100 + '亿字';
  if (v >= 10000) return Math.round(v / 1000) / 10 + '万字';
  return v ? v + '字' : '';
}
function sqStatus(st) {
  if (st === undefined || st === null || st === '') return '';
  return String(st) === '2' ? '完结' : '连载';
}
function sqStripTags(s) {
  return String(s || '').replace(/<[^>]+>/g, '');
}
function sqPlain(s) {
  return sqStripTags(String(s || '')).replace(/\s+/g, ' ').trim();
}
function sqEnt(s) {
  return String(s || '').replace(/&nbsp;/gi, ' ').replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/&amp;/gi, '&');
}

// ---------- 内部地址 -> bookId ----------
function sqBookId(u) {
  var s = String(u || '');
  var m = s.match(/\/sq(?:book|toc)\/(\d+)/);
  if (m) return m[1];
  m = s.match(/[?&]bookId=(\d+)/);
  return m ? m[1] : '';
}
// 详情阶段 keep('bid') 后，目录/正文优先读书籍变量，省一次正则且不怕地址变形
function sqBidOf(ctx) {
  var b = (ctx && ctx.book) || {};
  var id = sqBookId(b.tocUrl) || sqBookId(b.bookUrl);
  if (id) return id;
  try { id = String((b.vars || {}).bid || ''); } catch (e) { id = ''; }
  return id;
}

// ============================================================
// 正文净化：把原 content.replace 的四条规则搬进脚本
// 目的：段评按行号对齐，行号必须在净化之后确定；引擎的 replace 在
//       comments 之前执行且会合并空行，会把行号整体挪位。
// 输出保证：一行一段，没有空行。
// ============================================================
function sqClean(text) {
  var t = String(text || '').replace(/\r\n?/g, '\n');
  t = t.replace(/(?:请记住本站|请收藏本站|最新网址是|永久域名是|备用域名是|发布页是|最新章节请|本章未完，请点击|手机版阅读网址|一秒记住|免费阅读)[^\n]{0,60}/g, '');
  t = t.replace(/(?:书旗小说|书旗app|www\.shuqi\.com|m\.shuqi\.com)[^\n]{0,40}/g, '');
  t = t.replace(/[ \t\u3000]*[（(]本章完[）)][ \t\u3000]*/g, '');
  t = sqEnt(t);
  var parts = t.split('\n');
  var out = [];
  for (var i = 0; i < parts.length; i++) {
    var line = parts[i].replace(/^[\s\u3000\u200b]+|[\s\u3000\u200b]+$/g, '');
    if (line) out.push(line);
  }
  return out.join('\n');
}

// ---------- 缓存小工具（cache 无 delete，用 1 秒过期代替） ----------
function sqCacheGet(k) {
  try { var v = cache.get(k); return (v === undefined || v === null) ? '' : String(v); } catch (e) { return ''; }
}
function sqCachePut(k, v, ttl) {
  try { cache.put(k, String(v), ttl || 600); } catch (e) {}
}
function sqCacheDrop(k) {
  try { cache.put(k, '', 1); } catch (e) {}
}

// ============================================================
// 阶段脚本：搜索
// ============================================================
function sqSearch(ctx) {
  var key = String(ctx.key || '');
  var ts = String(Date.now());
  var req = sqAppBody({ page: 'searchResultV3', query: key, timestamp: ts }, null, ts);
  var res = http.post(SQ.host + '/sqan/render/render/search/native_v3', req.body, { headers: req.headers });
  if (!res.ok) throw new Error('搜索请求失败（HTTP ' + res.status + '）');
  var j = res.json();
  var out = [];
  function walk(n, depth) {
    if (!n || depth > 8) return;
    if (Array.isArray(n)) { for (var i = 0; i < n.length; i++) walk(n[i], depth + 1); return; }
    if (typeof n !== 'object') return;
    var bid = n.bookId || n.id || n.bid;
    var nm = n.bookName || n.title;
    var bookish = n.authorName || n.author || n.imgUrl || n.cover || n.coverUrl
      || n.wordCount || n.tags || n.tagList || n.desc !== undefined || n.briefIntro;
    if (bid && nm && bookish) {
      out.push({
        name: sqPlain(nm),
        author: sqPlain(n.authorName || n.author || ''),
        bookUrl: '/sqbook/' + String(bid),
        coverUrl: String(n.imgUrl || n.cover || n.coverUrl || ''),
        intro: sqPlain(n.briefIntro || n.intro || n.desc || n.recommendReason || ''),
        wordCount: sqWan(n.wordCount || n.words),
        status: sqStatus(n.serialState !== undefined ? n.serialState : (n.state !== undefined ? n.state : n.bookStatus)),
        lastChapter: sqPlain(n.latestChapterName || n.lastChapter || (n.latest_chapter && n.latest_chapter.cname) || ''),
        kind: [sqPlain(n.categoryName || n.category || n.first_category_name || ''),
               (n.tags || n.tagList || []).map(function (t) { return typeof t === 'string' ? t : (t && t.tagName) || ''; }).filter(function (x) { return !!x; }).join(',')]
              .filter(function (x) { return !!x; }).join(',')
      });
    } else {
      for (var k in n) if (n.hasOwnProperty(k)) walk(n[k], depth + 1);
    }
  }
  walk(j.data || j, 0);
  var seen = {}, uniq = [];
  for (var u = 0; u < out.length; u++) {
    var key2 = out[u].name + '|' + out[u].author;
    if (seen[key2]) continue;
    seen[key2] = 1;
    uniq.push(out[u]);
  }
  if (!uniq.length) throw new Error('搜索无结果（服务端返回 ' + String((j && j.message) || j.status || '空') + '）');
  return uniq;
}

// ============================================================
// 阶段脚本：详情（顺带把 bookId 记进书籍变量）
// ============================================================
function sqDetail(ctx) {
  var bid = sqBidOf(ctx);
  if (!bid) throw new Error('无法从书籍地址取 bookId');
  var tsD = String(Date.now());
  var req = sqAppBody({ bookId: bid }, null, tsD);
  var res = http.post(SQ.host + '/sqan/sqapi/bff/api/v1/reader/titlepage', req.body, { headers: req.headers });
  if (!res.ok) throw new Error('详情请求失败（HTTP ' + res.status + '）');
  var j = res.json();
  var b = ((j.data || {}).bookInfo) || {};
  if (!b.bookId) throw new Error('详情为空：' + String((j && j.message) || ''));
  var kind = [];
  if (b.className) kind.push(sqPlain(b.className));
  var tags = b.tag || b.tagList || b.tags || [];
  for (var i = 0; i < tags.length; i++) {
    var t = tags[i];
    kind.push(sqPlain(typeof t === 'string' ? t : (t && t.tagName) || ''));
  }
  var st = sqStatus(b.serialState !== undefined ? b.serialState : (b.state !== undefined ? b.state : b.bookStatus));
  if (st) kind.push(st);
  var sc = (b.scoreInfo && b.scoreInfo.bookScore) || b.score;
  if (sc) kind.push(sc + '分');
  var lc = b.lastChapter || b.latestChapter || b.firstChapter;
  var bookId = String(b.bookId || bid);
  try { keep('bid', bookId); } catch (e) {}
  // 段评预热：详情阶段把起点书号与整本目录拉好（各带超时），之后每章只发 1 个统计请求。
  // 放在这里而不是正文阶段，是为了不把 1.6 MB 目录塞进「打开章节」的等待路径。
  try {
    if (dpOn()) {
      var qb0 = dpBookId({ book: { name: sqPlain(b.bookName || b.title || ''), author: sqPlain(b.authorName || b.author || '') } });
      if (qb0) qdCatalog(qb0);
    }
  } catch (eDp) { try { log('段评预热跳过：' + (eDp && eDp.message || eDp)); } catch (eDp2) {} }
  return {
    name: sqPlain(b.bookName || b.title || ''),
    author: sqPlain(b.authorName || b.author || ''),
    intro: sqPlain(b.desc || b.briefIntro || b.intro || b.recIntro || ''),
    kind: kind.filter(function (x) { return !!x; }).join(','),
    coverUrl: String(b.imgUrl || b.coverUrl || b.cover || ''),
    wordCount: sqWan(b.wordCount),
    lastChapter: sqPlain((lc && lc.chapterName) ? lc.chapterName : (b.latestChapterName || b.finalChapterName || '')),
    status: st,
    bookUrl: '/sqbook/' + bookId,
    tocUrl: '/sqtoc/' + bookId
  };
}

// ============================================================
// 阶段脚本：目录
// 主路：H5 目录页一次返回整本（含真章名）；回退：chapterinfo 递推
// ============================================================
function sqToc(ctx) {
  var bid = sqBidOf(ctx);
  if (!bid) throw new Error('无法从目录地址取 bookId');
  var rows = sqTocFromH5(bid);
  if (rows && rows.length) return rows;
  return sqTocByIndex(bid);
}

function sqTocFromH5(bid) {
  var res = http.get('https://www.shuqi.com/chapter?bid=' + bid, { headers: { 'User-Agent': SQ.ua } });
  if (!res.ok || !res.body) return null;
  var html = res.body;
  if (html.indexOf('cid=') < 0) return null;
  // 实测（V8 / 1.19 MB / 2451 章）：while+exec 约 4.9 ms，replace 回调反而 5.7 ms —— 保留 while 写法
  var re = /href="\/reader\?bid=(\d+)&(?:amp;)?cid=(\d+)"[^>]*>([\s\S]*?)<\/a>/gi;
  var out = [], seen = {};
  var m;
  while ((m = re.exec(html)) !== null) {
    var cid = m[2];
    if (seen[cid]) continue;
    seen[cid] = 1;
    var raw = m[3].replace(/<i[^>]*>[\s\S]*?<\/i>/gi, ' ').replace(/<[^>]*>/g, ' ');
    raw = sqEnt(raw).replace(/\s+/g, ' ').trim();
    var title = raw.replace(/^\d+[.、]\s*/, '').trim();
    if (!title) continue;
    var isVip = /vip-tag|VIP/.test(m[0]);
    out.push({ title: title, url: '/sqch/' + m[1] + '/' + cid, isVip: isVip, isPay: isVip });
  }
  if (!out.length) return null;
  try { log('目录走 H5：' + out.length + ' 章'); } catch (e) {}
  return out;
}

function sqTocByIndex(bid) {
  var r1 = sqAppBody({ bookId: bid }, SQ.ciUid);
  var res1 = http.post(SQ.host + '/sqan/sqapi/bff/api/v1/reader/chapterinfo', r1.body, { headers: r1.headers });
  if (!res1.ok) throw new Error('目录探测失败（HTTP ' + res1.status + '）');
  var ch1 = ((res1.json().data || {}).chapter) || {};
  var base = Number(ch1.chapterId || 0);
  if (!base) throw new Error('目录探测未取到首章');

  var r2 = sqAppBody({ bookId: bid });
  var res2 = http.post(SQ.host + '/sqan/sqapi/bff/api/v1/reader/titlepage', r2.body, { headers: r2.headers });
  var total = 0;
  if (res2.ok) total = Number((((res2.json().data || {}).bookInfo) || {}).chapterTotalNum || 0);
  if (!(total > 0)) total = 1;

  var out = [];
  for (var i = 0; i < total; i++) {
    out.push({
      title: i === 0 ? sqPlain(ch1.name || '第1章') : ('第' + (i + 1) + '章'),
      url: '/sqch/' + bid + '/' + (base + i),
      isVip: false,
      isPay: false
    });
  }
  try { log('目录走递推回退：' + total + ' 章（章名为占位）'); } catch (e2) {}
  return out;
}

// ============================================================
// 阶段脚本：发现（榜单）
// ============================================================
function sqExplore(ctx) {
  var url = String(ctx.url || '');
  var m = url.match(/\/sqrank\/(male|female)\/(\d+)(?:\/(\d+))?/);
  if (!m) throw new Error('发现分类地址异常：' + url);
  var groupKey = m[1], ruleId = m[2], rankId = m[3] || '40';
  var page = String(Number(ctx.page || 1) || 1);
  var ts = String(Date.now());
  var req = sqAppBody({ ruleId: ruleId, rankId: rankId, groupKey: groupKey, page: page }, null, ts);
  var res = http.post(SQ.host + '/sqan/sqapi/bff/api/v2/bookrank/details', req.body, { headers: req.headers });
  if (!res.ok) throw new Error('榜单请求失败（HTTP ' + res.status + '）');
  var j = res.json();
  var d = j.data || {};

  function rows(list) {
    var out = [];
    for (var i = 0; i < (list || []).length; i++) {
      var b = list[i];
      var bid = b.bookId || b.id;
      if (!bid) continue;
      if (String(b.top_class || b.topClass || '') === '777') continue;
      var tags = b.tagList || b.tags || [];
      var tagStr = [];
      for (var t = 0; t < tags.length; t++) {
        var one = tags[t];
        tagStr.push(typeof one === 'string' ? one : ((one && one.tagName) || ''));
      }
      var info = [];
      if (b.attrs) info.push(sqPlain(b.attrs));
      if (b.categoryName) info.push(sqPlain(b.categoryName));
      if (b.wordCount) info.push(sqWan(b.wordCount));
      var st = sqStatus(b.serialState !== undefined ? b.serialState : b.state);
      if (st) info.push(st);
      if (b.score) info.push(b.score + '分');
      if (b.rankScoreSimple) info.push(String(b.rankScoreSimple));
      out.push({
        name: sqPlain(b.bookName || b.title || ''),
        author: sqPlain(b.authorName || b.author || ''),
        bookUrl: '/sqbook/' + String(bid),
        coverUrl: String(b.imgUrl || b.cover || b.coverUrl || ''),
        intro: sqPlain(b.briefIntro || b.intro || b.desc || b.recommendReason || ''),
        wordCount: sqWan(b.wordCount || b.words),
        status: st,
        lastChapter: sqPlain(b.latestChapterName || b.lastChapter || ''),
        kind: [tagStr.filter(function (x) { return !!x; }).join(','), info.join('·')]
              .filter(function (x) { return !!x; }).join(',')
      });
    }
    return out;
  }

  var all = [];
  if (d.bookList && d.bookList.length) {
    all = rows(d.bookList);
  } else {
    var cyc = d.cycleList || [];
    for (var c = 0; c < cyc.length; c++) {
      all = all.concat(rows((cyc[c] || {}).bookList));
    }
  }
  if (!all.length) {
    // 翻到底：第 2 页以后没数据就安静收尾，别弹错误
    if (Number(ctx.page || 1) > 1) return [];
    throw new Error('榜单无数据：' + String((j && j.message) || (j && j.status) || '空'));
  }
  return all;
}

// ============================================================
// 段评 · 设置项
// ============================================================
function dpOn() {
  var v = '';
  try { v = String(vars.get('dpMode') || ''); } catch (e) { v = ''; }
  return v !== '关';
}
function dpOffset() {
  var n = 0;
  try { n = Number(vars.get('dpOffset')); } catch (e) { n = 0; }
  if (!isFinite(n)) n = 0;
  if (n < -5) n = -5;
  if (n > 5) n = 5;
  return Math.trunc(n);
}
// 段评中间结果保留在 cache；页面规则直接读取本次正文返回的 data。

// 面板里把「正文行号」换算成「起点段落号」：pid = 行号 + 1 + 偏移
function dpParaId(lineIndex, offRaw) {
  var off = Number(offRaw);
  if (!isFinite(off)) off = 0;
  if (off < -5) off = -5;
  if (off > 5) off = 5;
  return Number(lineIndex) + 1 + Math.trunc(off);
}

// ============================================================
// 段评 · 起点数据链
// 归一：去掉「第N章」「第N卷」前缀、空白、书名号内多余符号
// ============================================================
function dpNorm(s) {
  var t = String(s == null ? '' : s).replace(/<[^>]+>/g, '');
  t = t.replace(/^\s*第\s*[0-9零一二三四五六七八九十百千万两]+\s*[卷部]\s*/, '');
  // 分卷书标题是「第十一卷 卷名 第两千四百四十六章 章名」：去掉卷号后章号还在中间，
  // 这里把「到第一个第N章为止」的前缀一起切掉；标题里没有章号时该条不匹配，原样保留
  t = t.replace(/^.*?第\s*[0-9零一二三四五六七八九十百千万两]+\s*[章回节]\s*[：:、.．\-—\s]*/, '');
  t = t.replace(/^\s*第\s*[0-9零一二三四五六七八九十百千万两]+\s*[章回节]\s*[：:、.．\-—\s]*/, '');
  t = t.replace(/[（(][^）)]*[）)]\s*$/, '');
  return t.replace(/[\s\u3000]+/g, '').trim();
}

function qdHeaders(tk) {
  var h = {
    'User-Agent': QD.ua,
    'Referer': QD.host + '/',
    'Accept': 'application/json, text/plain, */*'
  };
  if (tk) h['Cookie'] = '_csrfToken=' + tk;
  return h;
}

// 宽松键：去掉标点与「(上)(下)」标记，用来兜「书旗用逗号、起点用顿号」这类差异
function dpLoose(s) {
  var t = dpNorm(s);
  t = t.replace(/[（(]\s*[上下中]\s*[）)]/g, '');
  t = t.replace(/[，,。.、；;：:！!？?·—－_'"“”‘’《》<>\[\]【】()（）～~]/g, '');
  return t;
}

// 起点 SSR 页把整份数据塞在一个 JSON script 里，直接 JSON.parse 比正则快一个量级
function qdPageData(html) {
  var m = String(html || '').match(/id="vite-plugin-ssr_pageContext"[^>]*>([\s\S]*?)<\/script>/);
  if (!m) return null;
  var j = null;
  try { j = JSON.parse(m[1]); } catch (e) { return null; }
  var pc = (j && j.pageContext) || j;
  return ((pc || {}).pageProps || {}).pageData || null;
}

// 书旗书 → 起点 bookId：缓存 → 搜书页 SSR JSON 精确匹配（书名 + 作者）
function dpBookId(ctx) {
  // 只有自动匹配（书名 + 作者）；匹配不到时该章没有气泡，正文不受影响
  var b = (ctx && ctx.book) || {};
  var nm = String(b.name || '').replace(/<[^>]+>/g, '').replace(/[\s\u3000]+/g, '');
  var au = String(b.author || '').replace(/<[^>]+>/g, '').replace(/[\s\u3000]+/g, '');
  if (!nm) return '';

  var ck = 'dpb_' + nm + '|' + au;
  var hit = sqCacheGet(ck);
  if (hit) return hit;

  var res = http.get(QD.host + '/soushu/' + encodeURIComponent(nm) + '.html', { headers: qdHeaders(''), timeout: 8000 });
  if (!res.ok || !res.body) return '';
  var pd = qdPageData(res.body);
  var recs = (pd && pd.bookInfo && pd.bookInfo.records) || [];
  var pick = '';
  for (var i = 0; i < recs.length; i++) {
    var r = recs[i] || {};
    var rn = String(r.bName || '').replace(/[\s\u3000]+/g, '');
    var ra = String(r.bAuth || '').replace(/[\s\u3000]+/g, '');
    if (rn !== nm) continue;
    if (au && ra && ra !== au) continue;
    pick = String(r.bid || '');
    if (pick) break;
  }
  if (!pick) {
    for (var k = 0; k < recs.length; k++) {
      var r2 = recs[k] || {};
      if (String(r2.bName || '').replace(/[\s\u3000]+/g, '') === nm && r2.bid) { pick = String(r2.bid); break; }
    }
  }
  if (pick) {
    sqCachePut(ck, pick, 604800);
    try { log('段评：书旗《' + nm + '》→ 起点 ' + pick); } catch (e1) {}
  }
  return pick;
}

// 起点整本目录：一次请求拿全（长书约 1.7 MB），解析后按归一化章名建表并缓存
function qdCatalog(bid) {
  var ck = 'dpc_' + bid;
  var hit = sqCacheGet(ck);
  if (hit) {
    try { return JSON.parse(hit); } catch (e) {}
  }
  var res = http.get(QD.host + '/book/' + bid + '/catalog/', { headers: qdHeaders(''), timeout: 15000 });
  if (!res.ok || !res.body) return null;
  var pd = qdPageData(res.body);
  if (!pd) return null;
  var vs = pd.vs || [];
  var map = {};
  var n = 0;
  for (var i = 0; i < vs.length; i++) {
    var cs = (vs[i] || {}).cs || [];
    for (var k = 0; k < cs.length; k++) {
      var c = cs[k] || {};
      if (!c.id) continue;
      var nm = dpNorm(c.cN);
      if (!nm) continue;
      if (!map[nm]) { map[nm] = String(c.id); n++; }
    }
  }
  if (!n) return null;
  sqCachePut(ck, JSON.stringify(map), 259200);
  try { log('段评：起点目录 ' + n + ' 章（bookId=' + bid + '）'); } catch (e2) {}
  return map;
}

// 书旗章名 → 起点 chapterId：精确 → 包含（比例闸门）
function dpChapterId(bid, title) {
  var ck = 'dpch_' + bid + '|' + title;
  var hit = sqCacheGet(ck);
  if (hit) return hit;
  var map = qdCatalog(bid);
  if (!map) return '';
  var want = dpNorm(title);
  var cid = want ? (map[want] || '') : '';
  // 书旗把一拆二的章写成「第230章(上)降服」，起点是「第230章 降服」——去掉开头的（上/下/中）再试一次
  if (!cid && want) {
    var w2 = want.replace(/^[（(]\s*[上下中]\s*[）)]/, '');
    if (w2 && w2 !== want && map[w2]) cid = map[w2];
  }
  // 宽松键：去标点后完全相等才认；同一宽松键出现两次视为有歧义，放弃
  if (!cid && want) {
    var cw = dpLoose(want);
    if (cw && cw.length >= 3) {
      var found = '', dup = false;
      for (var kk in map) {
        if (!map.hasOwnProperty(kk)) continue;
        if (dpLoose(kk) !== cw) continue;
        if (found) { dup = true; break; }
        found = map[kk];
      }
      if (!dup && found) cid = found;
    }
  }
  // 书旗常在章名后面补半句（「旧地重游，秀水高风」↔ 起点「旧地重游」）：只用前半句再试一次
  if (!cid && want) {
    var head = want.split(/[，,]/)[0];
    if (head && head.length >= 2 && head !== want) {
      var found2 = '', dup2 = false;
      for (var hk in map) {
        if (!map.hasOwnProperty(hk)) continue;
        if (String(hk).split(/[，,]/)[0] !== head) continue;
        if (found2) { dup2 = true; break; }
        found2 = map[hk];
      }
      if (!dup2 && found2) cid = found2;
    }
  }
  // 包含：短的那个必须是长的开头（≥4 字），避免「剑」配到「剑气」
  if (!cid && want && want.length >= 4) {
    for (var k in map) {
      if (!map.hasOwnProperty(k)) continue;
      if (k.length < 4) continue;
      var pre = (want.indexOf(k) === 0) || (k.indexOf(want) === 0);
      if (!pre) continue;
      cid = map[k]; break;
    }
  }
  if (cid) sqCachePut(ck, cid, 259200);
  return cid;
}

// 访客令牌：服务端只校验「Cookie 与参数里的 _csrfToken 相同」，随机 UUID 即可
function dpToken() {
  var t = sqCacheGet('dptk');
  if (t) return t;
  t = uuid();
  sqCachePut('dptk', t, 604800);
  return t;
}

function dpSummary(bid, cid, tk) {
  var u = QD.host + '/majax/chapterReview/reviewSummary?bookId=' + encodeURIComponent(bid)
    + '&chapterId=' + encodeURIComponent(cid) + '&_csrfToken=' + encodeURIComponent(tk);
  var res = http.get(u, { headers: qdHeaders(tk), timeout: 8000 });
  if (!res.ok) return null;
  var j = null;
  try { j = res.json(); } catch (e) { return null; }
  if (!j || String(j.code) !== '0') return null;
  var list = ((j.data || {}).list) || [];
  var map = {}, chapterTotal = 0, hit = 0;
  for (var i = 0; i < list.length; i++) {
    var it = list[i] || {};
    var pid = Number(it.paragraphId);
    var n = Number(it.textCount || 0);
    if (pid === -1) { chapterTotal = n; continue; }
    if (!(pid > 0) || !(n > 0)) continue;
    map[pid] = n;
    hit++;
  }
  return { map: map, total: chapterTotal, hit: hit };
}

// ============================================================
// 阶段脚本：正文（正文 + 净化 + 段评计数）
// ============================================================
function sqContent(ctx) {
  var chUrl = String((ctx.chapter && ctx.chapter.url) || '');
  var m = chUrl.match(/\/sqch\/(\d+)\/(\d+)/);
  if (!m) throw new Error('章节地址异常：' + chUrl);
  var bid = m[1], cid = m[2];

  var raw = sqCdn(bid, cid);
  if (!raw) raw = sqChapterApi(bid, cid);
  if (!raw) throw new Error('正文没取到（chapterId=' + cid + '）');

  var text = sqClean(raw);
  if (!text) throw new Error('正文为空（chapterId=' + cid + '）');

  var out = { text: text };
  if (!dpOn()) return out;

  try {
    var qb = dpBookId(ctx);
    if (!qb) return out;
    var qc = dpChapterId(qb, (ctx.chapter && ctx.chapter.title) || '');
    if (!qc) return out;
    var tk = dpToken();
    try { if (String(cookie.get(QD.host + '/', '_csrfToken') || '') !== tk) cookie.set(QD.host + '/', '_csrfToken=' + tk); } catch (eCk) {}
    var s = dpSummary(qb, qc, tk);
    if (!s) {
      try { log('段评：统计接口无数据（bookId=' + qb + ' chapterId=' + qc + '）'); } catch (e1) {}
      return out;
    }
    var off = dpOffset();
    var lines = text.split('\n');
    var counts = {};
    var used = 0;
    for (var pid in s.map) {
      if (!s.map.hasOwnProperty(pid)) continue;
      var line = Number(pid) - 1 - off;   // pid = line + 1 + off
      if (line < 0 || line >= lines.length) continue;
      counts[String(line)] = s.map[pid];
      used++;
    }
    out.qdBid = String(qb);
    out.qdCid = String(qc);
    out.qdToken = tk;
    out.counts = counts;
    out.chapterTotal = s.total;
    // 匹配记录保留在内存 cache，供设置页自检。
    try { cache.put('dpLast', JSON.stringify({ b: String(qb), c: String(qc), t: tk }), 86400); } catch (eL) {}
    try {
      log('段评：' + used + '/' + s.hit + ' 段命中（偏移 ' + off + '，整章 ' + s.total + ' 条）');
    } catch (e2) {}
  } catch (e) {
    try { log('段评跳过：' + (e && e.message || e)); } catch (e3) {}
  }
  return out;
}

// 免签 CDN 缓存口；命中组合记忆在 cache，稳态只发 1 个请求
function sqCdn(bid, cid) {
  var flags = ['3111111111', '2111111111'];
  var hosts = ['c1.shuqireader.com', 'c2.shuqireader.com'];
  var pref = sqCacheGet('sqCdnPref');
  var order = [];
  if (pref) order.push(pref);
  for (var h = 0; h < hosts.length; h++) {
    for (var f = 0; f < flags.length; f++) {
      var k = hosts[h] + '|' + flags[f];
      if (k !== pref) order.push(k);
    }
  }
  for (var i = 0; i < order.length; i++) {
    var seg = order[i].split('|');
    var u = 'http://' + seg[0] + '/httpserver/filecache/get_book_content_'
      + bid + '_' + cid + '_' + seg[1] + '_0_0.html';
    var res = http.get(u);
    if (!res.ok || !res.body) continue;
    var body = res.body;
    var a = body.indexOf('(');
    if (a > 0) { body = body.substring(a + 1); var b = body.lastIndexOf(')'); if (b > 0) body = body.substring(0, b); }
    var arr = null;
    try { arr = JSON.parse(body); } catch (e) { arr = null; }
    if (arr && arr.length && arr[0] && arr[0].content != null) {
      var t = String(arr[0].content).replace(/<br\s*\/?>/gi, '\n');
      t = sqStripTags(t);
      if (t.replace(/\s/g, '').length > 0) {
        if (pref !== order[i]) sqCachePut('sqCdnPref', order[i], 86400);
        return t;
      }
    }
  }
  return '';
}

// 加密口兜底：chapterinfo 返回 base64，需 ALG-5 解码
function sqChapterApi(bid, cid) {
  var tsC = String(Date.now());
  var r = sqAppBody({ bookId: bid, chapterId: cid }, SQ.ciUid, tsC);
  var res = http.post(SQ.host + '/sqan/sqapi/bff/api/v1/reader/chapterinfo', r.body, { headers: r.headers });
  if (!res.ok) return '';
  var ch = ((res.json().data || {}).chapter) || {};
  if (!ch.content) return '';
  return sqDecodeContent(ch.content);
}

