function sqActClearDp(ctx) {
  var last = null;
  try { last = JSON.parse(String(cache.get('dpLast') || 'null')); } catch (e) {}
  sqCacheDrop('dptk');
  if (last && last.b) sqCacheDrop('dpc_' + String(last.b));
  sqCacheDrop('dpLast');
  sqCacheDrop('sqCdnPref');
  return '已清除最近记录、令牌与该书起点目录缓存；刷新本章后重新取数。';
}

function sqActCdnProbe(ctx) {
  var hosts = ['c1.shuqireader.com', 'c2.shuqireader.com'];
  var flags = ['3111111111', '2111111111'];
  var best = '', bestMs = 1e9;
  var lines = [];
  for (var h = 0; h < hosts.length; h++) {
    var u = 'http://' + hosts[h] + '/httpserver/filecache/get_book_content_34078_2180322_3111111111_0_0.html';
    var t0 = Date.now();
    var res = http.get(u, { timeout: 8000 });
    var ms = Date.now() - t0;
    var ok = res.ok && res.body && res.body.length > 200;
    lines.push(hosts[h] + ' ' + (ok ? ms + 'ms' : '失败'));
    if (ok && ms < bestMs) { bestMs = ms; best = hosts[h] + '|' + flags[0]; }
  }
  if (best) sqCachePut('sqCdnPref', best, 86400);
  return lines.join(' / ') + (best ? '，已选 ' + best.split('|')[0] : '，全部失败，保持自动');
}

// 一键自检：把面板要走的两个接口在脚本里跑一遍，告诉用户哪一段断了
function sqActDpCheck(ctx) {
  var last = null;
  try { last = JSON.parse(String(cache.get('dpLast') || 'null')); } catch (e) { last = null; }
  if (!last || !last.b || !last.c) return '还没有匹配记录：先打开一本书的章节（段评开着），再回来点这里';
  var b = String(last.b), c = String(last.c), t = String(last.t || '');
  if (!t) t = uuid();
  var s = dpSummary(b, c, t);
  var out = '起点 ' + b + ' / 章 ' + c;
  out += s ? (' · 统计 OK：' + s.hit + ' 段有评论，整章 ' + s.total + ' 条') : ' · 统计失败';
  var u = QD.host + '/majax/chapterReview/reviewList?bookId=' + b + '&chapterId=' + c
    + '&paragraphId=1&page=1&pageSize=20&_csrfToken=' + encodeURIComponent(t);
  var r = http.get(u, { headers: qdHeaders(t), timeout: 8000 });
  if (!r.ok) return out + ' · 列表失败（HTTP ' + r.status + '）';
  var n = -1;
  try { n = (((r.json().data) || {}).list || []).length; } catch (e) { n = -1; }
  return out + (n >= 0 ? (' · 列表 OK：首页 ' + n + ' 条') : ' · 列表返回非 JSON');
}

function sqActReset(ctx) {
  vars.set('dpMode', '开');
  vars.set('dpOffset', '0');
  sqActClearDp(ctx);
  return '段评开关、段落偏移已恢复默认；请刷新本章。';
}
